{
  "project": {
    "name": "Personalised Local AI Coding Assistant",
    "vision": "Build a fully local, privacy-preserving AI coding assistant that progressively learns how an individual developer works, remembers their coding history, understands their projects, and replicates their coding preferences and behavioural patterns.",
    "core_objective": "Create a personalisation and continuous-learning layer around existing open-weight foundation models. We do not intend to train a foundation model from scratch or build a custom inference engine. We intend to leverage existing models, local inference runtimes, memory systems, and parameter-efficient fine-tuning techniques.",
    "starting_point": "We are evaluating the open-source Footprint project (Amanlabh/footprint) as a starting point. Review its existing architecture, implementation, capabilities and limitations before proposing changes. Reuse existing components wherever appropriate rather than rebuilding everything."
  },
  "project_philosophy": {
    "principles": [
      "Everything should run locally, including inference, personal memory storage and LoRA training.",
      "Each user must have an independent personalisation environment.",
      "No user's private coding history, memory or LoRA training data should be mixed with another user's data.",
      "Memory and LoRA are complementary and equally important components of personalisation.",
      "The system should remain independent of any particular foundation model.",
      "Use existing open-source tools, frameworks and runtimes wherever possible.",
      "Avoid unnecessary infrastructure, complexity and resource consumption.",
      "Prioritise measurable improvements in coding behaviour and task completion over theoretical improvements."
    ],
    "important_distinction": {
      "memory": "Retains explicit knowledge, project context, historical decisions, coding preferences and previous task outcomes.",
      "lora": "Learns recurring behavioural patterns, coding conventions, implementation preferences and problem-solving approaches from an individual's historical coding interactions.",
      "combined_objective": "Memory provides the relevant knowledge and context at inference time, while LoRA helps the foundation model behave more consistently with the developer's established coding style."
    }
  },
  "four_core_pillars": {
    "1_intelligence": {
      "objective": "Identify the most capable open-weight foundation model for our local coding assistant.",
      "approach": "We will initially shortlist and compare multiple foundation models. However, we do not want to optimise the entire project around one particular model. Our personalisation and memory architecture must be model-independent.",
      "candidate_models": [
        {
          "name": "Qwen2.5-Coder-1.5B",
          "role": "Original Footprint baseline"
        },
        {
          "name": "Qwen3.5-9B",
          "role": "First higher-capacity candidate"
        },
        {
          "name": "Qwen3.5-27B",
          "role": "Higher-capacity comparison, subject to hardware feasibility and exact model availability"
        },
        {
          "name": "Gemma 4 12B",
          "role": "Alternative foundation model"
        },
        {
          "name": "Gemma 4 26B A4B",
          "role": "Larger mixture-of-experts comparison, subject to hardware feasibility and exact model availability"
        },
        {
          "name": "NVIDIA Nemotron",
          "role": "Additional model family to evaluate, including relevant coding and agentic capabilities"
        }
      ],
      "requirements": [
        "Verify the exact model names, released checkpoints, parameter counts, licences and hardware requirements before implementation.",
        "Evaluate coding capabilities, reasoning, debugging, code modification and multi-step task completion.",
        "Evaluate tool calling, agentic capabilities and compatibility with local coding environments.",
        "Evaluate supported context lengths.",
        "Measure memory requirements, inference speed, temperature, power consumption and hardware utilisation.",
        "Do not assume quantisation is the default approach. First investigate higher-precision inference and larger models where hardware permits.",
        "Quantisation can be explored as an optimisation option if necessary, but should not be an architectural dependency.",
        "Support loading different foundation models without rebuilding the memory and personalisation infrastructure.",
        "Only one large foundation model needs to be active at a time. Multiple models may be downloaded locally and switched when required."
      ],
      "expected_deliverables": [
        "Foundation model comparison matrix",
        "Hardware compatibility assessment",
        "Local inference architecture",
        "Model abstraction and switching mechanism",
        "Recommended initial foundation model"
      ]
    },
    "2_personalisation": {
      "objective": "Teach the foundation model to replicate an individual's coding behaviour, preferences and problem-solving patterns using user-specific LoRA adapters.",
      "primary_approach": "LoRA (Low-Rank Adaptation) and parameter-efficient fine-tuning.",
      "core_hypothesis": "The longer a developer uses the assistant, the more examples and evidence we can collect about their actual coding behaviour. This can help us create a richer and more representative training dataset for their individual LoRA adapter.",
      "important_clarification": "More historical data does not automatically mean better training. Quality, diversity, correctness, recency and relevance of examples must determine which interactions enter the training dataset.",
      "what_we_want_the_model_to_learn": [
        "Preferred coding style and structure",
        "Naming conventions",
        "Preferred frameworks and libraries",
        "Approach to debugging",
        "Problem-solving patterns",
        "Preferred levels of abstraction and complexity",
        "How the developer handles errors",
        "How the developer modifies AI-generated code",
        "Patterns in accepted and rejected implementations",
        "Recurring coding preferences and conventions"
      ],
      "pipeline": [
        {
          "step": 1,
          "name": "Interaction collection",
          "description": "Capture prompts, responses, code changes, tool calls, errors, corrections and final task outcomes."
        },
        {
          "step": 2,
          "name": "Task segmentation",
          "description": "Divide historical interactions into individual coding tasks and meaningful learning examples."
        },
        {
          "step": 3,
          "name": "Behaviour extraction",
          "description": "Identify recurring coding patterns, implementation preferences, corrections and accepted approaches."
        },
        {
          "step": 4,
          "name": "Training example generation",
          "description": "Convert relevant interactions into structured input-output examples suitable for supervised fine-tuning."
        },
        {
          "step": 5,
          "name": "Quality filtering",
          "description": "Remove irrelevant, duplicated, incorrect and low-quality examples. Distinguish accepted implementations from rejected AI suggestions."
        },
        {
          "step": 6,
          "name": "Training dataset preparation",
          "description": "Create structured training, validation and held-out test datasets. Prevent leakage between training and evaluation."
        },
        {
          "step": 7,
          "name": "LoRA fine-tuning",
          "description": "Train a user-specific adapter locally using suitable parameter-efficient fine-tuning frameworks."
        },
        {
          "step": 8,
          "name": "Adapter evaluation",
          "description": "Evaluate the new adapter against the existing adapter and unmodified foundation model."
        },
        {
          "step": 9,
          "name": "Adapter versioning",
          "description": "Maintain version history, approval, rollback and periodic retraining capabilities."
        }
      ],
      "adapter_architecture": {
        "requirement": "Each user should have an independent LoRA adapter for each compatible foundation model.",
        "example": {
          "user_A": {
            "qwen": "User A Qwen Adapter",
            "gemma": "User A Gemma Adapter"
          },
          "user_B": {
            "qwen": "User B Qwen Adapter",
            "gemma": "User B Gemma Adapter"
          }
        },
        "note": "Adapters should not be assumed to be transferable across different foundation model architectures."
      },
      "efficiency_optimisation": {
        "objective": "Make LoRA training, storage, updating and inference as resource-efficient as possible.",
        "areas_to_investigate": [
          "Optimal LoRA rank and alpha",
          "Target modules and trainable parameter selection",
          "Training dataset quality versus quantity",
          "Training frequency and minimum data thresholds",
          "Incremental versus periodic full adapter retraining",
          "Adapter storage and version management",
          "Training compute and memory requirements",
          "Adapter loading and inference overhead",
          "Catastrophic forgetting and regression prevention",
          "Methods for retaining previously learned coding patterns"
        ],
        "instruction": "Compare available LoRA and PEFT optimisation techniques. Recommend an implementation based on measured benefits rather than introducing complexity prematurely."
      },
      "expected_deliverables": [
        "Interaction collection engine",
        "Behaviour extraction pipeline",
        "Structured LoRA training dataset",
        "Local fine-tuning workflow",
        "Per-user adapter management",
        "Adapter versioning and rollback mechanism",
        "Training efficiency recommendations"
      ]
    },
    "3_memory": {
      "objective": "Build a structured memory system that retains useful information from historical interactions and supplies relevant context to the foundation model without repeatedly passing entire conversation histories.",
      "primary_hypothesis": "Regardless of whether the historical interaction spans one month, three months or a year, the memory system should convert it into a consistent, structured representation. The foundation model should receive relevant, selected information from this representation rather than the entire conversation history.",
      "important_design_principle": "The output of the memory pipeline must follow a predefined schema. The schema should remain consistent regardless of conversation duration, volume or the underlying foundation model.",
      "memory_pipeline": [
        {
          "step": 1,
          "name": "Ingestion",
          "description": "Collect historical coding conversations, tasks, code modifications and relevant outcomes."
        },
        {
          "step": 2,
          "name": "Task segmentation",
          "description": "Divide conversations into meaningful coding tasks, sessions and project discussions."
        },
        {
          "step": 3,
          "name": "Cleaning",
          "description": "Remove noise, irrelevant content, redundant information and unnecessary conversation details."
        },
        {
          "step": 4,
          "name": "Information extraction",
          "description": "Extract developer preferences, project facts, technical decisions, constraints, implementations, corrections and outcomes."
        },
        {
          "step": 5,
          "name": "Classification",
          "description": "Classify extracted information into predefined memory categories."
        },
        {
          "step": 6,
          "name": "Scoring",
          "description": "Score information based on relevance, usefulness, reliability, recency, frequency and confidence."
        },
        {
          "step": 7,
          "name": "Deduplication and reconciliation",
          "description": "Merge repeated information, identify contradictions and update outdated information while preserving useful historical evidence."
        },
        {
          "step": 8,
          "name": "Structured storage",
          "description": "Store information in a predefined, versioned and model-independent schema."
        },
        {
          "step": 9,
          "name": "Continuous updating",
          "description": "Update existing memories when new interactions provide better or more recent information."
        }
      ],
      "memory_categories": {
        "user_profile": {
          "description": "Long-term developer preferences and coding behaviour.",
          "examples": [
            "Preferred programming languages",
            "Coding conventions",
            "Naming preferences",
            "Preferred frameworks",
            "General coding style",
            "Working preferences"
          ]
        },
        "project_memory": {
          "description": "Technical knowledge and decisions associated with individual projects.",
          "examples": [
            "Project architecture",
            "Technology stack",
            "Database schema",
            "API integrations",
            "Technical decisions",
            "Dependencies",
            "Constraints",
            "Known issues"
          ]
        },
        "session_memory": {
          "description": "Current task state and continuity information.",
          "examples": [
            "Current task",
            "Completed work",
            "Files modified",
            "Pending work",
            "Errors encountered",
            "Next steps"
          ]
        },
        "historical_task_memory": {
          "description": "Historical coding tasks and their outcomes.",
          "examples": [
            "Previous bugs",
            "Successful implementations",
            "Rejected approaches",
            "Debugging solutions",
            "Important corrections",
            "Reusable coding patterns"
          ]
        }
      },
      "retrieval_architecture": {
        "objective": "Retrieve relevant memory dynamically based on the current coding task.",
        "components": [
          {
            "name": "BM25",
            "role": "Keyword-based retrieval."
          },
          {
            "name": "Semantic retrieval",
            "role": "Find conceptually relevant information using embeddings."
          },
          {
            "name": "Metadata filtering",
            "role": "Filter by project, memory type, date and other relevant attributes."
          },
          {
            "name": "Deduplication",
            "role": "Remove overlapping retrieval results."
          },
          {
            "name": "Reranking",
            "role": "Prioritise the most relevant retrieved records."
          },
          {
            "name": "Context builder",
            "role": "Convert selected memories into a structured context package for the foundation model."
          }
        ],
        "retrieval_flow": [
          "Receive a new coding task.",
          "Identify the relevant project and task type.",
          "Filter the memory database.",
          "Run BM25 retrieval.",
          "Run semantic retrieval.",
          "Merge and deduplicate results.",
          "Rerank candidate memories.",
          "Select the most useful information.",
          "Build a structured context package.",
          "Send the context package to the active foundation model."
        ]
      },
      "context_efficiency": {
        "objective": "Control context length and avoid unnecessary token consumption.",
        "requirements": [
          "Never send entire historical conversation histories by default.",
          "Use the same predefined memory schema regardless of the amount of historical data.",
          "Retrieve only information relevant to the current task.",
          "Prioritise concise, high-value information.",
          "Maintain project context separately from session continuity.",
          "Support context budgets and relevance thresholds.",
          "Preserve provenance and timestamps.",
          "Allow the context builder to work with different foundation models."
        ],
        "important_clarification": "A consistent structured memory schema does not imply that every memory record should be sent to the model. The schema is the storage and interchange format; retrieval determines which subset is actually included in each prompt."
      },
      "memory_and_training_relationship": {
        "description": "The interaction collection and extraction pipeline should produce two separate outputs.",
        "output_A": {
          "name": "Operational memory",
          "purpose": "Provide explicit knowledge and historical context during inference."
        },
        "output_B": {
          "name": "Curated training dataset",
          "purpose": "Provide high-quality behavioural examples for LoRA fine-tuning."
        },
        "requirement": "Do not use the complete operational memory database as a LoRA training dataset. Create a separate curated dataset with appropriate training examples."
      },
      "expected_deliverables": [
        "Memory extraction pipeline",
        "Predefined structured memory schema",
        "Four independent memory categories",
        "Local memory database",
        "BM25 retrieval",
        "Semantic retrieval",
        "Hybrid retrieval and reranking",
        "Context builder",
        "Memory update and reconciliation mechanism"
      ]
    },
    "4_evaluation": {
      "objective": "Prove that foundation model selection, LoRA personalisation and memory retrieval improve real-world coding performance.",
      "approach": "Establish controlled experiments that isolate the contribution of each component.",
      "experimental_design": [
        {
          "experiment": "A",
          "configuration": "Base foundation model, no memory, no LoRA",
          "purpose": "Establish baseline performance."
        },
        {
          "experiment": "B",
          "configuration": "Base foundation model with memory, without LoRA",
          "purpose": "Measure the contribution of memory."
        },
        {
          "experiment": "C",
          "configuration": "Base foundation model with LoRA, without memory",
          "purpose": "Measure the contribution of behavioural personalisation."
        },
        {
          "experiment": "D",
          "configuration": "Base foundation model with memory and LoRA",
          "purpose": "Measure the combined contribution."
        }
      ],
      "metrics": {
        "coding_quality": [
          "Task completion rate",
          "Test pass rate",
          "Code quality",
          "Correctness",
          "Number of corrections required"
        ],
        "personalisation": [
          "Adherence to developer coding preferences",
          "Consistency with previous implementations",
          "Similarity to accepted coding patterns",
          "Reduction in repeated corrections",
          "Ability to follow project-specific conventions"
        ],
        "memory_quality": [
          "Retrieval precision",
          "Retrieval recall",
          "Relevance of retrieved memories",
          "Duplicate retrieval rate",
          "Context token consumption",
          "Impact of retrieved memory on task completion"
        ],
        "system_performance": [
          "Inference latency",
          "Model loading time",
          "Memory usage",
          "CPU/GPU utilisation",
          "Temperature",
          "Power consumption"
        ]
      },
      "requirements": [
        "Use identical starting repositories, prompts, tools and evaluation conditions.",
        "Maintain separate training, validation and held-out test datasets.",
        "Prevent leakage between training and evaluation tasks.",
        "Evaluate on both previously encountered and unseen coding tasks.",
        "Compare memory-only, LoRA-only and combined approaches.",
        "Measure both coding quality and behavioural personalisation.",
        "Maintain reproducible evaluation records.",
        "Do not activate a new adapter unless it passes defined quality and regression checks."
      ],
      "expected_deliverables": [
        "Coding task benchmark dataset",
        "Evaluation harness",
        "Memory retrieval evaluation",
        "LoRA evaluation framework",
        "Controlled experiment reports",
        "Adapter approval mechanism",
        "Continuous performance monitoring"
      ]
    }
  },
  "implementation_strategy": {
    "overall_direction": "Prioritise building the personalisation and memory infrastructure before committing to a final foundation model. Once these systems are functional, evaluate different foundation models using the same personalisation and memory architecture.",
    "phases": [
      {
        "phase": 1,
        "name": "Architecture and baseline",
        "focus": "Understand Footprint, inspect its existing implementation, establish the local development environment and define interfaces.",
        "outputs": [
          "Existing architecture assessment",
          "Initial foundation model baseline",
          "System architecture",
          "Data flow definition",
          "Initial benchmark tasks"
        ]
      },
      {
        "phase": 2,
        "name": "Interaction and personalisation data pipeline",
        "focus": "Capture developer interactions, segment tasks, extract behavioural patterns and curate LoRA training examples.",
        "outputs": [
          "Interaction collector",
          "Task segmentation",
          "Behaviour extraction",
          "Training data schema",
          "Training data quality filters"
        ]
      },
      {
        "phase": 3,
        "name": "LoRA implementation and optimisation",
        "focus": "Build a local LoRA fine-tuning workflow and optimise adapter efficiency.",
        "outputs": [
          "First personal LoRA adapter",
          "Training workflow",
          "Adapter version management",
          "Initial personalisation comparison"
        ]
      },
      {
        "phase": 4,
        "name": "Structured memory pipeline",
        "focus": "Build memory extraction, classification, scoring, deduplication and structured storage.",
        "outputs": [
          "Memory schema",
          "User profile memory",
          "Project memory",
          "Session memory",
          "Historical task memory",
          "Memory update mechanism"
        ]
      },
      {
        "phase": 5,
        "name": "Hybrid retrieval and context construction",
        "focus": "Integrate BM25, semantic retrieval, metadata filtering and reranking.",
        "outputs": [
          "BM25 search",
          "Embedding-based retrieval",
          "Hybrid retrieval engine",
          "Context builder",
          "Context budget management"
        ]
      },
      {
        "phase": 6,
        "name": "Foundation model comparison",
        "focus": "Evaluate Qwen, Gemma, Nemotron and other suitable models using the same architecture.",
        "outputs": [
          "Model comparison",
          "Hardware assessment",
          "Inference compatibility",
          "Recommended foundation model"
        ]
      },
      {
        "phase": 7,
        "name": "Integrated evaluation",
        "focus": "Run controlled experiments across foundation models, memory configurations and LoRA configurations.",
        "outputs": [
          "Baseline versus personalised comparison",
          "Memory versus LoRA comparison",
          "Combined performance comparison",
          "Retrieval evaluation",
          "Final architecture recommendations"
        ]
      },
      {
        "phase": 8,
        "name": "Continuous learning and productisation",
        "focus": "Automate memory updates, curated data generation, periodic LoRA training, evaluation and deployment of approved adapters.",
        "outputs": [
          "Continuous learning pipeline",
          "Automated adapter update workflow",
          "User isolation",
          "Local model management",
          "Production-ready application"
        ]
      }
    ]
  },
  "technical_constraints": {
    "deployment": "Fully local deployment is the intended product architecture.",
    "inference": "Use existing local inference runtimes. Do not build a custom inference engine.",
    "training": "LoRA training should run locally using existing fine-tuning frameworks and compatible hardware.",
    "model_loading": "Only one large foundation model needs to be active at a time. Support switching between downloaded models.",
    "quantisation": "Do not assume quantisation is mandatory. Evaluate higher-precision models first and use quantisation only when justified by measured hardware constraints.",
    "storage": "All user-specific conversations, memory, training datasets and adapters must be stored locally and isolated.",
    "modularity": "Memory, retrieval, personalisation, model inference and evaluation should have clearly defined interfaces.",
    "privacy": "No external custom inference or training service should be required for the core product.",
    "hardware": "The implementation must assess hardware compatibility before finalising model size and training configurations."
  },
  "instructions_to_the_advanced_llm": {
    "role": "Act as a senior AI systems architect, machine learning engineer, LLM fine-tuning specialist and technical product strategist.",
