      },
      {
        "section": 12,
        "title": "Open Decisions",
        "requirement": "List decisions that require further information, particularly hardware, operating system, target users, model licensing and deployment constraints."
      }
    ],
    "quality_requirements": [
      "Be technically detailed but explain concepts clearly.",
      "Prefer practical implementation recommendations over theoretical descriptions.",
      "Use diagrams, tables and examples wherever they improve understanding.",
      "Do not provide generic AI architecture recommendations disconnected from this project.",
