    ]
  },
  "final_expected_outcome": {
    "description": "Produce a technically actionable blueprint for building a fully local, privacy-preserving, personalised AI coding assistant.",
    "success_criteria": [
      "The system can run open-weight coding models locally.",
      "The system captures and processes individual coding interactions.",
